<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><div><a class="small" href="/admin/orders">← Orders</a><h1>Order <?= e($o['number']) ?></h1><span class="small muted"><a href="/admin/customers/<?= (int)$o['cid'] ?>"><?= e($o['name'] ?: $o['email']) ?></a> · <?= e($o['created_at']) ?> UTC</span></div><?php $badge($o['status']); ?></div>
<div class="grid g2" style="align-items:start"><div class="panel"><h2>Items</h2><?php foreach ($items as $i): $io = (array)($i['opts'] ?? []); $chips = array_filter(['Province' => isset($io['province']) ? ((['FED' => 'Federal'] + App\Catalog::PROVINCES)[$io['province']] ?? $io['province']) : null, 'Domain' => $io['domain'] ?? null, 'Ending' => isset($io['tld']) ? '.' . $io['tld'] : null, 'Note' => $io['note'] ?? null]); ?>
  <div class="oi"><div class="row spread small"><span><b><?= e($i['name']) ?></b> <span class="muted">· <?= e(label($i['billing'])) ?></span></span><b><?= money((int)$i['unit_cents']) ?><?= $i['setup_cents'] ? ' + ' . money((int)$i['setup_cents']) : '' ?></b></div>
    <?php if ($chips): ?><p class="oi-chips"><?php foreach ($chips as $ck => $cv): ?><span><?= e($ck) ?>: <b><?= e((string)$cv) ?></b></span><?php endforeach; ?></p><?php endif; ?>
    <?php if (!empty($io['details']) && is_array($io['details'])): ?><details class="oi-d" open><summary>What the customer entered</summary><?php $fa_slug = $i['service_slug']; $fa_data = $io['details']; include APP_ROOT . '/views/partials/form-answers.php'; ?></details><?php endif; ?>
  </div><?php endforeach; ?>
  <p class="small" style="margin-top:10px">Subtotal <?= money((int)$o['subtotal_cents']) ?> · discount <?= money((int)$o['discount_cents']) ?> · tax <?= money((int)$o['tax_cents']) ?> · <b>total <?= money((int)$o['total_cents']) ?></b><?= $o['coupon_code'] ? ' · code ' . e($o['coupon_code']) : '' ?></p>
  <p class="small muted">Stripe session: <?= e($o['stripe_session_id'] ?: '—') ?></p></div>
<div><div class="panel"><h2>Payments</h2><?php if (!$payments): ?><p class="small muted">No payments recorded.</p><?php endif; ?><?php foreach ($payments as $p): ?><div class="small"><?= e($p['provider']) ?> · <?= e($p['provider_ref']) ?> · <?= money((int)$p['amount_cents']) ?> · <?= e($p['status']) ?> · <?= e($p['created_at']) ?></div><?php endforeach; ?>
  <?php if (in_array($o['status'], ['pending', 'awaiting_payment'], true)): ?><form method="post" action="/admin/orders/<?= e($o['number']) ?>/mark-paid" style="margin-top:12px" data-confirm="Mark this order as paid? This starts project delivery."><?= App\Csrf::field() ?><label for="ref">Received offline (e-Transfer / cheque) — reference</label><div class="row"><input id="ref" name="reference" type="text" required style="flex:1"><button class="btn btn-primary btn-sm">Mark paid</button></div></form><?php endif; ?></div>
<div class="panel"><h2>Projects</h2><?php if (!$projects): ?><p class="small muted">Created automatically after payment.</p><?php endif; ?><?php foreach ($projects as $p): ?><div class="row spread small"><a href="/admin/projects/<?= e($p['number']) ?>"><?= e($p['title']) ?></a><?php $badge($p['status']); ?></div><?php endforeach; ?></div></div></div>
